# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.soccer_step_collision.cache_contract": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import KEYS, constants\nfrom .scene_config import validate, SCENE_NAME\n\nfrom .runtime_support import HERE, ROOT\ndef signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    s=d['scenario']; validate(s)\n    if d['scene'] != SCENE_NAME or d.get('simulation_signature') != signature(s):\n        raise ValueError('Stale or foreign physics cache; resimulate')\n    count=round(s['render']['fps']*s['render']['duration_sec'])\n    if len(d['frames']) != count or d['frame_end'] != count: raise ValueError('Incomplete trajectory')\n    if not d['quality']['valid']: raise ValueError('Physics trace failed validation')\n    for i,row in enumerate(d['frames']):\n        if row['frame_index'] != i+1 or abs(row['time_sec']-i/d['fps'])>1e-9:\n            raise ValueError('Invalid frame clock')\n        for k in KEYS:\n            if not all(math.isfinite(v) for field in ('location','quaternion_xyzw','linear_velocity','angular_velocity') for v in row[k][field]):\n                raise ValueError('Nonfinite rigid-body state')\n", "scene_support.soccer_step_collision.plant_styling": "\"\"\"Integrate the supplied fig scan with neutral ceramics and room lighting.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nimport bpy\n\ndef ceramic_planter(base,material_factory):\n    clay=material_factory('Warm greige matte stoneware',(.30,.27,.22),.76,.0007)\n    # A hollow tapered sleeve surrounds the original small scanned pot.\n    profile=[(.126,0),(.131,.009),(.176,.260),(.180,.270),(.180,.280),\n             (.176,.285),(.169,.283),(.165,.271),(.122,.028)]\n    n=80; vertices=[]; faces=[]\n    for radius,z in profile:\n        vertices.extend([(radius*math.cos(i*math.tau/n),radius*math.sin(i*math.tau/n),z) for i in range(n)])\n    for j in range(len(profile)-1):\n        for i in range(n):\n            a=j*n+i; b=j*n+(i+1)%n; c=(j+1)*n+(i+1)%n; d=(j+1)*n+i\n            faces.append((a,b,c,d))\n    faces.append(tuple(reversed(range(n))))\n    faces.append(tuple((len(profile)-1)*n+i for i in range(n)))\n    mesh=bpy.data.meshes.new('Closed hollow stoneware profile'); mesh.from_pydata(vertices,[],faces); mesh.update()\n    obj=bpy.data.objects.new('Matte ceramic outer planter',mesh); bpy.context.collection.objects.link(obj)\n    obj.location=base; mesh.materials.append(clay)\n    for f in mesh.polygons: f.use_smooth=len(f.vertices)==4\n    soil=material_factory('Dark potting soil',(.025,.018,.009),.97,.003)\n    bpy.ops.mesh.primitive_cylinder_add(vertices=80,radius=.164,depth=.016,location=(base.x,base.y,base.z+.252))\n    bpy.context.object.name='Recessed potting soil'; bpy.context.object.data.materials.append(soil)\n    return obj\n\ndef integrate_scan(plant,height):\n    \"\"\"Remove the scan's cyan cast while retaining its original UV and leaf detail.\"\"\"\n    for mat in plant.data.materials:\n        if not mat or not mat.use_nodes: continue\n        images=[node.image for node in mat.node_tree.nodes if node.type=='TEX_IMAGE' and node.image]\n        if not images: raise ValueError('Fiddle Leaf Fig material has no albedo texture')\n        albedo=images[0]; nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        nodes.clear()\n        tex=nodes.new('ShaderNodeTexImage'); tex.image=albedo\n        luminance=nodes.new('ShaderNodeRGBToBW'); links.new(tex.outputs['Color'],luminance.inputs[0])\n        tonal=nodes.new('ShaderNodeMapRange'); tonal.inputs['From Min'].default_value=.025\n        tonal.inputs['From Max'].default_value=.60\n        links.new(luminance.outputs[0],tonal.inputs['Value'])\n        green=nodes.new('ShaderNodeValToRGB')\n        green.color_ramp.elements[0].color=(.025,.065,.012,1)\n        green.color_ramp.elements[1].color=(.24,.36,.065,1)\n        green.color_ramp.elements.new(.45).color=(.075,.155,.024,1)\n        links.new(tonal.outputs[0],green.inputs[0])\n        blend=nodes.new('ShaderNodeMixRGB'); blend.inputs[0].default_value=.68\n        links.new(tex.outputs['Color'],blend.inputs[1]); links.new(green.outputs[0],blend.inputs[2])\n        leaf=nodes.new('ShaderNodeBsdfPrincipled')\n        leaf.inputs['Roughness'].default_value=.64\n        leaf.inputs['Specular IOR Level'].default_value=.25\n        leaf.inputs['Subsurface Weight'].default_value=.025\n        links.new(blend.outputs[0],leaf.inputs['Base Color'])\n        brown=nodes.new('ShaderNodeValToRGB')\n        brown.color_ramp.elements[0].color=(.018,.010,.005,1)\n        brown.color_ramp.elements[1].color=(.18,.10,.035,1)\n        links.new(tonal.outputs[0],brown.inputs[0])\n        stem=nodes.new('ShaderNodeBsdfPrincipled'); stem.inputs['Roughness'].default_value=.85\n        links.new(brown.outputs[0],stem.inputs['Base Color'])\n        coord=nodes.new('ShaderNodeTexCoord'); xyz=nodes.new('ShaderNodeSeparateXYZ')\n        links.new(coord.outputs['Object'],xyz.inputs[0])\n        mask=nodes.new('ShaderNodeMapRange'); mask.inputs['From Min'].default_value=height*.43\n        mask.inputs['From Max'].default_value=height*.55\n        links.new(xyz.outputs['Z'],mask.inputs['Value'])\n        mix=nodes.new('ShaderNodeMixShader'); links.new(mask.outputs[0],mix.inputs[0])\n        links.new(stem.outputs[0],mix.inputs[1]); links.new(leaf.outputs[0],mix.inputs[2])\n        out=nodes.new('ShaderNodeOutputMaterial'); links.new(mix.outputs[0],out.inputs['Surface'])\n", "scene_support.soccer_step_collision.runtime_support": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\nMODELS = ROOT / 'assets' / 'models'\nASSETS = ROOT / 'assets' / 'polyhaven' / 'soccer_step_collision'\n\nfrom pcve_scene_runtime import python_for, render_prefix\n", "scene_support.soccer_step_collision.scene_config": "\"\"\"Strict metre/kilogram/second scenario contract, shared by simulation and render.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\nfrom pathlib import Path\n\nSCENE_NAME = 'soccer_step_collision'\nBASELINE_PHYSICS = dict(soccer_mass=.43, basketball_mass=.62, launch_speed=1.95,\n    step_height=.045, surface_rolling_friction=.0015,\n    soccer_restitution=.72, basketball_restitution=.78)\nLIMITS = dict(soccer_mass=(.05,5), basketball_mass=(.05,5), launch_speed=(.1,3),\n    step_height=(.005,.20), surface_rolling_friction=(0,.1),\n    soccer_restitution=(0,1), basketball_restitution=(0,1))\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=4., resolution=[960,540], samples=40),\n        camera=dict(location=[-2.6,-5.5,2.15], target=[.55,.1,.35], lens_mm=48))\n\ndef merge(base, override):\n    result = deepcopy(base)\n    if not isinstance(override, dict): raise ValueError('Override must be an object')\n    for k,v in override.items():\n        if k not in base: raise ValueError(f'Unknown scenario field: {k}')\n        result[k] = merge(base[k],v) if isinstance(base[k],dict) else deepcopy(v)\n    return result\n\ndef finite(x):\n    return type(x) in (int,float) and math.isfinite(x)\n\ndef validate(s):\n    if set(s) != set(defaults()) or s['scene'] != SCENE_NAME or s['schema_version'] != 1:\n        raise ValueError('Wrong scenario schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown physics field')\n    for k,(lo,hi) in LIMITS.items():\n        if not finite(s['physics'][k]) or not lo <= s['physics'][k] <= hi:\n            raise ValueError(f'{k} must be within {lo}..{hi}')\n    r=s['render']\n    if set(r) != set(defaults()['render']): raise ValueError('Unknown render field')\n    if type(r['fps']) is not int or r['fps'] <= 0 or 1440 % r['fps']:\n        raise ValueError('fps must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not .1 <= r['duration_sec'] <= 30:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v<16 for v in r['resolution']):\n        raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples']<1: raise ValueError('Invalid samples')\n    c=s['camera']\n    if set(c) != set(defaults()['camera']): raise ValueError('Unknown camera field')\n    for k in ('location','target'):\n        if len(c[k]) != 3 or not all(finite(v) for v in c[k]): raise ValueError('Invalid camera vector')\n    if not finite(c['lens_mm']) or c['lens_mm']<=0: raise ValueError('Invalid lens')\n\ndef load_scenario(path=None, override=None):\n    s=defaults()\n    for p in (path,override):\n        if p: s=merge(s,json.loads(Path(p).read_text(encoding='utf-8')))\n    validate(s)\n    return s\n\ndef write_json(path, data):\n    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)\n    path.write_text(json.dumps(data,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')\n", "scene_support.soccer_step_collision.scene_environment": "\"\"\"A daylight split-level sitting room; all geometry is authored at metre scale.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nimport random\nimport bpy\nfrom mathutils import Vector, Matrix\nfrom .runtime_support import MODELS, ASSETS\nfrom .scene_geometry import boxes, ROOM_X, ROOM_Y\n\nPLANT_ASSET = 'fiddle_leaf_fig.glb'\nPLANT_HEIGHT_M = 1.24\nPLANT_POSITION_XY = (3.92, 1.82)\nPLANT_ROTATION_DEG = 135.\n\ndef material(name,color,roughness=.6,bump=0):\n    m=bpy.data.materials.new(name); m.use_nodes=True\n    bs=m.node_tree.nodes.get('Principled BSDF')\n    bs.inputs['Base Color'].default_value=(*color,1)\n    bs.inputs['Roughness'].default_value=roughness\n    if bump:\n        n=m.node_tree.nodes.new('ShaderNodeTexNoise'); n.inputs['Scale'].default_value=180\n        t=m.node_tree.nodes.new('ShaderNodeTexCoord')\n        m.node_tree.links.new(t.outputs['Object'],n.inputs['Vector'])\n        b=m.node_tree.nodes.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.22\n        b.inputs['Distance'].default_value=bump\n        m.node_tree.links.new(n.outputs['Fac'],b.inputs['Height'])\n        m.node_tree.links.new(b.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef cube(name,center,size,mat,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=center)\n    o=bpy.context.object; o.name=name; o.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    o.data.materials.append(mat)\n    if bevel:\n        mod=o.modifiers.new('Small real edge radius','BEVEL'); mod.width=bevel; mod.segments=3\n        o.modifiers.new('Weighted corner normals','WEIGHTED_NORMAL')\n    return o\n\ndef aim(obj,point):\n    obj.rotation_euler=(Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name,pos,target,power,size,color):\n    d=bpy.data.lights.new(name,'AREA'); d.energy=power; d.shape='DISK'; d.size=size; d.color=color\n    o=bpy.data.objects.new(name,d); bpy.context.collection.objects.link(o); o.location=pos; aim(o,target)\n\ndef scanned_surface(name,stem,scale,wood=False):\n    m=material(name,(.4,.35,.27),.48)\n    n,l=m.node_tree.nodes,m.node_tree.links; bs=n.get('Principled BSDF')\n    uv=n.new('ShaderNodeTexCoord'); mapping=n.new('ShaderNodeVectorMath'); mapping.operation='SCALE'\n    mapping.inputs['Scale'].default_value=scale\n    l.new(uv.outputs['Object'],mapping.inputs[0])\n    diff=n.new('ShaderNodeTexImage'); diff.image=bpy.data.images.load(str(ASSETS/f'{stem}_diff_2k.jpg'),check_existing=True)\n    l.new(mapping.outputs['Vector'],diff.inputs['Vector']); l.new(diff.outputs['Color'],bs.inputs['Base Color'])\n    if wood:\n        b=n.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.15; b.inputs['Distance'].default_value=.0015\n        l.new(diff.outputs['Color'],b.inputs['Height']); l.new(b.outputs[0],bs.inputs['Normal'])\n    else:\n        # Concrete source is weathered: lighten it into a sealed residential slab.\n        mix=n.new('ShaderNodeMixRGB'); mix.blend_type='MIX'; mix.inputs[0].default_value=.50\n        mix.inputs[2].default_value=(.46,.43,.37,1)\n        l.new(diff.outputs['Color'],mix.inputs[1]); l.new(mix.outputs[0],bs.inputs['Base Color'])\n        rough=n.new('ShaderNodeTexImage'); rough.image=bpy.data.images.load(str(ASSETS/f'{stem}_rough_2k.jpg'),check_existing=True)\n        rough.image.colorspace_settings.name='Non-Color'\n        l.new(mapping.outputs[0],rough.inputs['Vector'])\n        remap=n.new('ShaderNodeMapRange'); remap.inputs['To Min'].default_value=.38; remap.inputs['To Max'].default_value=.65\n        l.new(rough.outputs['Color'],remap.inputs['Value']); l.new(remap.outputs[0],bs.inputs['Roughness'])\n        norm=n.new('ShaderNodeTexImage'); norm.image=bpy.data.images.load(str(ASSETS/f'{stem}_nor_gl_2k.jpg'),check_existing=True)\n        norm.image.colorspace_settings.name='Non-Color'; l.new(mapping.outputs[0],norm.inputs['Vector'])\n        normal=n.new('ShaderNodeNormalMap'); normal.inputs['Strength'].default_value=.18\n        l.new(norm.outputs['Color'],normal.inputs['Color']); l.new(normal.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef import_mesh(path,name):\n    \"\"\"Evaluate GLB hierarchy/skin and bake once before rescaling in world units.\"\"\"\n    before=set(bpy.data.objects); bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=set(bpy.data.objects)-before\n    bpy.context.view_layer.update(); deps=bpy.context.evaluated_depsgraph_get(); result=[]\n    for o in imported:\n        if o.type!='MESH': continue\n        mesh=bpy.data.meshes.new_from_object(o.evaluated_get(deps),depsgraph=deps)\n        mesh.transform(o.matrix_world)\n        obj=bpy.data.objects.new(name,mesh); bpy.context.collection.objects.link(obj); result.append(obj)\n    for o in imported: bpy.data.objects.remove(o,do_unlink=True)\n    bpy.ops.object.select_all(action='DESELECT')\n    for o in result: o.select_set(True)\n    bpy.context.view_layer.objects.active=result[0]\n    if len(result)>1: bpy.ops.object.join()\n    return bpy.context.object\n\ndef make_ball(filename,key,radius):\n    o=import_mesh(MODELS/filename,key)\n    lo=Vector(tuple(min(v.co[i] for v in o.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in o.data.vertices) for i in range(3)))\n    c=(lo+hi)/2\n    outer=max((v.co-c).length for v in o.data.vertices)\n    for v in o.data.vertices: v.co=(v.co-c)*(radius/outer)\n    o.data.update(); o.name=key\n    for f in o.data.polygons: f.use_smooth=True\n    for m in o.data.materials:\n        if not m or not m.use_nodes: continue\n        for n in m.node_tree.nodes:\n            if n.type!='BSDF_PRINCIPLED': continue\n            for field,value in [('Metallic',0.),('Roughness',.57 if key=='soccer' else .72),('Emission Strength',0.)]:\n                for link in list(n.inputs[field].links): m.node_tree.links.remove(link)\n                n.inputs[field].default_value=value\n    # Fixed mesh-space orientation, independent of physical centre and quaternion.\n    o.data.transform(Matrix.Rotation(.36 if key=='soccer' else .55,4,'X') @ Matrix.Rotation(.38,4,'Z'))\n    return o\n\ndef build_room(s):\n    h=s['physics']['step_height']\n    plaster=material('Warm mineral plaster',(.62,.58,.49),.86,.0008)\n    cream=material('Ivory painted joinery',(.76,.74,.66),.44,.0002)\n    dark=material('Anodized bronze frames',(.065,.055,.042),.33)\n    oak=material('Oiled oak end grain',(.28,.15,.068),.50,.0007)\n    linen=material('Natural flax upholstery',(.50,.44,.34),.88,.0012)\n    concrete=scanned_surface('Sealed warm concrete','concrete_floor',.45)\n    wood=scanned_surface('Photographic worn oak floor','wood_floor_worn',.50,True)\n    for name,center,size in boxes(h):\n        if name=='back_wall': continue\n        cube(name,center,size,concrete if name=='floor' else wood if name=='platform' else plaster,\n             .0006 if name=='platform' else 0)\n    # Window opening in a continuous plaster wall; the actual daylight enters here.\n    y=ROOM_Y[1]+.1; xmin,xmax=ROOM_X; wl,wr=-1.75,.45; wb,wt=.82,2.72\n    for name,center,size in [\n        ('Back wall left',((xmin+wl)/2,y,1.6),(wl-xmin,.2,3.2)),\n        ('Back wall right',((wr+xmax)/2,y,1.6),(xmax-wr,.2,3.2)),\n        ('Under window',((wl+wr)/2,y,wb/2),(wr-wl,.2,wb)),\n        ('Above window',((wl+wr)/2,y,(wt+3.2)/2),(wr-wl,.2,3.2-wt))]: cube(name,center,size,plaster)\n    for x in (wl,wr,(wl+wr)/2): cube('Window vertical frame',(x,2.83,(wb+wt)/2),(.045,.08,wt-wb),dark,.002)\n    for z in (wb,wt,1.8): cube('Window horizontal frame',((wl+wr)/2,2.83,z),(wr-wl,.08,.042),dark,.002)\n    cube('Deep stone window sill',((wl+wr)/2,2.74,wb), (wr-wl+.1,.30,.05),cream,.006)\n    # Outdoor colour and a distant hedge give depth through the real opening.\n    sky=material('Overcast garden beyond window',(.62,.73,.80),1)\n    cube('Garden sky',(-.65,5.8,2.7),(6,.05,5.4),sky)\n    hedge=material('Soft garden green',(.12,.20,.075),.9,.02)\n    hn,hl=hedge.node_tree.nodes,hedge.node_tree.links\n    noise=hn.new('ShaderNodeTexNoise'); noise.inputs['Scale'].default_value=15\n    ramp=hn.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].color=(.025,.055,.012,1)\n    ramp.color_ramp.elements[1].color=(.19,.29,.085,1)\n    hl.new(noise.outputs['Fac'],ramp.inputs[0]); hl.new(ramp.outputs[0],hn.get('Principled BSDF').inputs['Base Color'])\n    rng=random.Random(92)\n    for i in range(17):\n        bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=rng.uniform(.3,.6),location=(-3+i*.3,5.2,rng.uniform(.25,.65)))\n        bpy.context.object.name='Distant garden foliage'; bpy.context.object.data.materials.append(hedge)\n        for f in bpy.context.object.data.polygons: f.use_smooth=True\n    glass=material('Lightly frosted privacy glazing',(.88,.94,.98),.25)\n    gn,gl=glass.node_tree.nodes,glass.node_tree.links\n    gbs=gn.get('Principled BSDF'); gbs.inputs['Transmission Weight'].default_value=1\n    gbs.inputs['IOR'].default_value=1.45\n    # Transmitted daylight is supplied by the exterior area light, without noisy caustics.\n    lightpath=gn.new('ShaderNodeLightPath'); transparent=gn.new('ShaderNodeBsdfTransparent')\n    mix=gn.new('ShaderNodeMixShader'); gl.new(lightpath.outputs['Is Shadow Ray'],mix.inputs[0])\n    gl.new(gbs.outputs[0],mix.inputs[1]); gl.new(transparent.outputs[0],mix.inputs[2])\n    gl.new(mix.outputs[0],gn.get('Material Output').inputs['Surface'])\n    cube('Privacy window glazing',((wl+wr)/2,2.88,(wb+wt)/2),(wr-wl,.008,wt-wb),glass)\n    # Low built-in bench stays well away from the ball lane (y=-0.18).\n    for x in (1.30,3.35): cube('Bench leg',(x,2.27,h+.19),(.075,.48,.38),oak,.009)\n    cube('Oak bench seat',(2.325,2.27,h+.395),(2.35,.64,.08),oak,.018)\n    cube('Flax seat cushion',(2.325,2.24,h+.47),(2.24,.57,.095),linen,.038)\n    # Wall artwork: physical frame, mat, paper and raised abstract pigment.\n    cube('Oak picture frame',(2.5,2.72,1.72),(.94,.05,1.08),oak,.006)\n    cube('Ivory print mount',(2.5,2.686,1.72),(.89,.012,1.03),cream)\n    paper=material('Textured cotton art paper',(.64,.57,.43),.94,.0005)\n    rust=material('Abstract clay pigment',(.35,.13,.065),.95)\n    cube('Artwork paper',(2.5,2.678,1.72),(.68,.006,.81),paper)\n    cube('Artwork pigment',(2.43,2.673,1.67),(.27,.002,.49),rust,.06)\n    cube('Artwork charcoal accent',(2.69,2.672,1.9),(.10,.002,.20),dark)\n    # Floor skirting follows both levels; the curb riser remains fully visible.\n    cube('Back skirting lower',(-1.9,2.785,.045),(3.8,.03,.09),cream,.002)\n    cube('Back skirting upper',(2.6,2.785,h+.045),(5.2,.03,.09),cream,.002)\n    cube('Right skirting',(5.185,-.5,h+.045),(.03,6.6,.09),cream,.002)\n    cube('Ceiling',(.7,-.5,3.26),(9.2,6.8,.12),cream)\n    # Keep the fig's original leaf/pot proportions with one uniform metre-scale factor.\n    plant=import_mesh(MODELS/PLANT_ASSET,'Fiddle Leaf Fig / supplied textured mesh')\n    lo=Vector(tuple(min(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    hi=Vector(tuple(max(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    native_height=hi.z-lo.z\n    if native_height<=0: raise ValueError('Fiddle Leaf Fig has zero height')\n    # Anchor the pot rather than the asymmetric canopy, and put its bottom on the slab.\n    base=[v.co for v in plant.data.vertices if v.co.z <= lo.z+native_height*.12]\n    center=Vector(((min(v.x for v in base)+max(v.x for v in base))/2,\n                   (min(v.y for v in base)+max(v.y for v in base))/2,lo.z))\n    scale=PLANT_HEIGHT_M/native_height\n    for v in plant.data.vertices: v.co=(v.co-center)*scale\n    plant.data.update()\n    plant.location=(*PLANT_POSITION_XY,h)\n    plant['source_asset']=str(MODELS/PLANT_ASSET)\n    plant['height_m']=PLANT_HEIGHT_M\n    plant['uniform_scale_from_source']=scale\n    plant.rotation_euler.z=math.radians(PLANT_ROTATION_DEG)\n    from .plant_styling import integrate_scan,ceramic_planter\n    integrate_scan(plant,PLANT_HEIGHT_M)\n    ceramic_planter(plant.location,material)\n    scene=bpy.context.scene\n    scene.world=bpy.data.worlds.new('Daylight interior world'); scene.world.use_nodes=True\n    bg=scene.world.node_tree.nodes.get('Background'); bg.inputs['Color'].default_value=(.65,.74,.84,1); bg.inputs['Strength'].default_value=.16\n    area('Large window soft daylight',(-.7,3.12,2.05),(.2,-.6,.1),360,1.9,(.84,.91,1.))\n    area('Warm interior bounce',(-2.8,-2.0,2.5),(.5,.3,.2),100,3.0,(1.,.86,.69))\n    area('Ceiling reflected light',(2.2,.2,3.05),(.5,-.3,0),80,2.5,(1.,.94,.83))\n    area('Soft reflected daylight near bench',(2.9,-.2,2.2),(3.92,1.82,.95),35,1.3,(1.,.96,.85))\n    # Grazing afternoon light casts the mullion shadows onto the lower floor.\n    bpy.ops.object.light_add(type='SUN',location=(-2,4,5))\n    sun=bpy.context.object; sun.name='Afternoon sun through rear window'; sun.data.energy=1.6\n    sun.data.angle=math.radians(7); sun.data.color=(1.,.89,.72); aim(sun,(.8,-1.4,0))\n", "scene_support.soccer_step_collision.scene_geometry": "\"\"\"One source of truth for visible surfaces and Bullet collision geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS = ('soccer','basketball')\nRADII = (.11,.12)\nSTART_X = (-1.55,.82)\nLANE_Y = -.18\nSIM_HZ = 1440\nROOM_X = (-3.8,5.2)\nROOM_Y = (-3.8,2.8)\nSTEP_X = 0.\nFLOOR_THICKNESS = .16\n\ndef boxes(height):\n    \"\"\"(name, centre, full size). Top surfaces are exactly z=0 and z=height.\"\"\"\n    x0,x1=ROOM_X; y0,y1=ROOM_Y\n    return [\n        ('floor',((x0+x1)/2,(y0+y1)/2,-FLOOR_THICKNESS/2),\n            (x1-x0,y1-y0,FLOOR_THICKNESS)),\n        ('platform',((STEP_X+x1)/2,(y0+y1)/2,height/2),\n            (x1-STEP_X,y1-y0,height)),\n        ('back_wall',((x0+x1)/2,y1+.10,1.6),(x1-x0,.20,3.2)),\n        ('right_wall',(x1+.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2)),\n        ('left_wall',(x0-.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2))]\n\ndef constants():\n    return dict(radii_m=RADII,start_x_m=START_X,lane_y_m=LANE_Y,\n                step_x_m=STEP_X,room_x_m=ROOM_X,room_y_m=ROOM_Y,simulation_hz=SIM_HZ,\n                floor_friction=.65,platform_friction=.65,surface_restitution=.22,\n                floor_rolling_friction=.0015,ball_lateral_friction=.8)\n", "scene_support.soccer_step_collision": "\"\"\"Soccer ball climbs a real curb and collides with a resting basketball.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "cache_contract": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import KEYS, constants\nfrom .scene_config import validate, SCENE_NAME\n\nfrom .runtime_support import HERE, ROOT\ndef signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    s=d['scenario']; validate(s)\n    if d['scene'] != SCENE_NAME or d.get('simulation_signature') != signature(s):\n        raise ValueError('Stale or foreign physics cache; resimulate')\n    count=round(s['render']['fps']*s['render']['duration_sec'])\n    if len(d['frames']) != count or d['frame_end'] != count: raise ValueError('Incomplete trajectory')\n    if not d['quality']['valid']: raise ValueError('Physics trace failed validation')\n    for i,row in enumerate(d['frames']):\n        if row['frame_index'] != i+1 or abs(row['time_sec']-i/d['fps'])>1e-9:\n            raise ValueError('Invalid frame clock')\n        for k in KEYS:\n            if not all(math.isfinite(v) for field in ('location','quaternion_xyzw','linear_velocity','angular_velocity') for v in row[k][field]):\n                raise ValueError('Nonfinite rigid-body state')\n", "plant_styling": "\"\"\"Integrate the supplied fig scan with neutral ceramics and room lighting.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nimport bpy\n\ndef ceramic_planter(base,material_factory):\n    clay=material_factory('Warm greige matte stoneware',(.30,.27,.22),.76,.0007)\n    # A hollow tapered sleeve surrounds the original small scanned pot.\n    profile=[(.126,0),(.131,.009),(.176,.260),(.180,.270),(.180,.280),\n             (.176,.285),(.169,.283),(.165,.271),(.122,.028)]\n    n=80; vertices=[]; faces=[]\n    for radius,z in profile:\n        vertices.extend([(radius*math.cos(i*math.tau/n),radius*math.sin(i*math.tau/n),z) for i in range(n)])\n    for j in range(len(profile)-1):\n        for i in range(n):\n            a=j*n+i; b=j*n+(i+1)%n; c=(j+1)*n+(i+1)%n; d=(j+1)*n+i\n            faces.append((a,b,c,d))\n    faces.append(tuple(reversed(range(n))))\n    faces.append(tuple((len(profile)-1)*n+i for i in range(n)))\n    mesh=bpy.data.meshes.new('Closed hollow stoneware profile'); mesh.from_pydata(vertices,[],faces); mesh.update()\n    obj=bpy.data.objects.new('Matte ceramic outer planter',mesh); bpy.context.collection.objects.link(obj)\n    obj.location=base; mesh.materials.append(clay)\n    for f in mesh.polygons: f.use_smooth=len(f.vertices)==4\n    soil=material_factory('Dark potting soil',(.025,.018,.009),.97,.003)\n    bpy.ops.mesh.primitive_cylinder_add(vertices=80,radius=.164,depth=.016,location=(base.x,base.y,base.z+.252))\n    bpy.context.object.name='Recessed potting soil'; bpy.context.object.data.materials.append(soil)\n    return obj\n\ndef integrate_scan(plant,height):\n    \"\"\"Remove the scan's cyan cast while retaining its original UV and leaf detail.\"\"\"\n    for mat in plant.data.materials:\n        if not mat or not mat.use_nodes: continue\n        images=[node.image for node in mat.node_tree.nodes if node.type=='TEX_IMAGE' and node.image]\n        if not images: raise ValueError('Fiddle Leaf Fig material has no albedo texture')\n        albedo=images[0]; nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        nodes.clear()\n        tex=nodes.new('ShaderNodeTexImage'); tex.image=albedo\n        luminance=nodes.new('ShaderNodeRGBToBW'); links.new(tex.outputs['Color'],luminance.inputs[0])\n        tonal=nodes.new('ShaderNodeMapRange'); tonal.inputs['From Min'].default_value=.025\n        tonal.inputs['From Max'].default_value=.60\n        links.new(luminance.outputs[0],tonal.inputs['Value'])\n        green=nodes.new('ShaderNodeValToRGB')\n        green.color_ramp.elements[0].color=(.025,.065,.012,1)\n        green.color_ramp.elements[1].color=(.24,.36,.065,1)\n        green.color_ramp.elements.new(.45).color=(.075,.155,.024,1)\n        links.new(tonal.outputs[0],green.inputs[0])\n        blend=nodes.new('ShaderNodeMixRGB'); blend.inputs[0].default_value=.68\n        links.new(tex.outputs['Color'],blend.inputs[1]); links.new(green.outputs[0],blend.inputs[2])\n        leaf=nodes.new('ShaderNodeBsdfPrincipled')\n        leaf.inputs['Roughness'].default_value=.64\n        leaf.inputs['Specular IOR Level'].default_value=.25\n        leaf.inputs['Subsurface Weight'].default_value=.025\n        links.new(blend.outputs[0],leaf.inputs['Base Color'])\n        brown=nodes.new('ShaderNodeValToRGB')\n        brown.color_ramp.elements[0].color=(.018,.010,.005,1)\n        brown.color_ramp.elements[1].color=(.18,.10,.035,1)\n        links.new(tonal.outputs[0],brown.inputs[0])\n        stem=nodes.new('ShaderNodeBsdfPrincipled'); stem.inputs['Roughness'].default_value=.85\n        links.new(brown.outputs[0],stem.inputs['Base Color'])\n        coord=nodes.new('ShaderNodeTexCoord'); xyz=nodes.new('ShaderNodeSeparateXYZ')\n        links.new(coord.outputs['Object'],xyz.inputs[0])\n        mask=nodes.new('ShaderNodeMapRange'); mask.inputs['From Min'].default_value=height*.43\n        mask.inputs['From Max'].default_value=height*.55\n        links.new(xyz.outputs['Z'],mask.inputs['Value'])\n        mix=nodes.new('ShaderNodeMixShader'); links.new(mask.outputs[0],mix.inputs[0])\n        links.new(stem.outputs[0],mix.inputs[1]); links.new(leaf.outputs[0],mix.inputs[2])\n        out=nodes.new('ShaderNodeOutputMaterial'); links.new(mix.outputs[0],out.inputs['Surface'])\n", "runtime_support": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\nMODELS = ROOT / 'assets' / 'models'\nASSETS = ROOT / 'assets' / 'polyhaven' / 'soccer_step_collision'\n\nfrom pcve_scene_runtime import python_for, render_prefix\n", "scene_config": "\"\"\"Strict metre/kilogram/second scenario contract, shared by simulation and render.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\nfrom pathlib import Path\n\nSCENE_NAME = 'soccer_step_collision'\nBASELINE_PHYSICS = dict(soccer_mass=.43, basketball_mass=.62, launch_speed=1.95,\n    step_height=.045, surface_rolling_friction=.0015,\n    soccer_restitution=.72, basketball_restitution=.78)\nLIMITS = dict(soccer_mass=(.05,5), basketball_mass=(.05,5), launch_speed=(.1,3),\n    step_height=(.005,.20), surface_rolling_friction=(0,.1),\n    soccer_restitution=(0,1), basketball_restitution=(0,1))\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=4., resolution=[960,540], samples=40),\n        camera=dict(location=[-2.6,-5.5,2.15], target=[.55,.1,.35], lens_mm=48))\n\ndef merge(base, override):\n    result = deepcopy(base)\n    if not isinstance(override, dict): raise ValueError('Override must be an object')\n    for k,v in override.items():\n        if k not in base: raise ValueError(f'Unknown scenario field: {k}')\n        result[k] = merge(base[k],v) if isinstance(base[k],dict) else deepcopy(v)\n    return result\n\ndef finite(x):\n    return type(x) in (int,float) and math.isfinite(x)\n\ndef validate(s):\n    if set(s) != set(defaults()) or s['scene'] != SCENE_NAME or s['schema_version'] != 1:\n        raise ValueError('Wrong scenario schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown physics field')\n    for k,(lo,hi) in LIMITS.items():\n        if not finite(s['physics'][k]) or not lo <= s['physics'][k] <= hi:\n            raise ValueError(f'{k} must be within {lo}..{hi}')\n    r=s['render']\n    if set(r) != set(defaults()['render']): raise ValueError('Unknown render field')\n    if type(r['fps']) is not int or r['fps'] <= 0 or 1440 % r['fps']:\n        raise ValueError('fps must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not .1 <= r['duration_sec'] <= 30:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v<16 for v in r['resolution']):\n        raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples']<1: raise ValueError('Invalid samples')\n    c=s['camera']\n    if set(c) != set(defaults()['camera']): raise ValueError('Unknown camera field')\n    for k in ('location','target'):\n        if len(c[k]) != 3 or not all(finite(v) for v in c[k]): raise ValueError('Invalid camera vector')\n    if not finite(c['lens_mm']) or c['lens_mm']<=0: raise ValueError('Invalid lens')\n\ndef load_scenario(path=None, override=None):\n    s=defaults()\n    for p in (path,override):\n        if p: s=merge(s,json.loads(Path(p).read_text(encoding='utf-8')))\n    validate(s)\n    return s\n\ndef write_json(path, data):\n    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)\n    path.write_text(json.dumps(data,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')\n", "scene_environment": "\"\"\"A daylight split-level sitting room; all geometry is authored at metre scale.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nimport random\nimport bpy\nfrom mathutils import Vector, Matrix\nfrom .runtime_support import MODELS, ASSETS\nfrom .scene_geometry import boxes, ROOM_X, ROOM_Y\n\nPLANT_ASSET = 'fiddle_leaf_fig.glb'\nPLANT_HEIGHT_M = 1.24\nPLANT_POSITION_XY = (3.92, 1.82)\nPLANT_ROTATION_DEG = 135.\n\ndef material(name,color,roughness=.6,bump=0):\n    m=bpy.data.materials.new(name); m.use_nodes=True\n    bs=m.node_tree.nodes.get('Principled BSDF')\n    bs.inputs['Base Color'].default_value=(*color,1)\n    bs.inputs['Roughness'].default_value=roughness\n    if bump:\n        n=m.node_tree.nodes.new('ShaderNodeTexNoise'); n.inputs['Scale'].default_value=180\n        t=m.node_tree.nodes.new('ShaderNodeTexCoord')\n        m.node_tree.links.new(t.outputs['Object'],n.inputs['Vector'])\n        b=m.node_tree.nodes.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.22\n        b.inputs['Distance'].default_value=bump\n        m.node_tree.links.new(n.outputs['Fac'],b.inputs['Height'])\n        m.node_tree.links.new(b.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef cube(name,center,size,mat,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=center)\n    o=bpy.context.object; o.name=name; o.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    o.data.materials.append(mat)\n    if bevel:\n        mod=o.modifiers.new('Small real edge radius','BEVEL'); mod.width=bevel; mod.segments=3\n        o.modifiers.new('Weighted corner normals','WEIGHTED_NORMAL')\n    return o\n\ndef aim(obj,point):\n    obj.rotation_euler=(Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name,pos,target,power,size,color):\n    d=bpy.data.lights.new(name,'AREA'); d.energy=power; d.shape='DISK'; d.size=size; d.color=color\n    o=bpy.data.objects.new(name,d); bpy.context.collection.objects.link(o); o.location=pos; aim(o,target)\n\ndef scanned_surface(name,stem,scale,wood=False):\n    m=material(name,(.4,.35,.27),.48)\n    n,l=m.node_tree.nodes,m.node_tree.links; bs=n.get('Principled BSDF')\n    uv=n.new('ShaderNodeTexCoord'); mapping=n.new('ShaderNodeVectorMath'); mapping.operation='SCALE'\n    mapping.inputs['Scale'].default_value=scale\n    l.new(uv.outputs['Object'],mapping.inputs[0])\n    diff=n.new('ShaderNodeTexImage'); diff.image=bpy.data.images.load(str(ASSETS/f'{stem}_diff_2k.jpg'),check_existing=True)\n    l.new(mapping.outputs['Vector'],diff.inputs['Vector']); l.new(diff.outputs['Color'],bs.inputs['Base Color'])\n    if wood:\n        b=n.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.15; b.inputs['Distance'].default_value=.0015\n        l.new(diff.outputs['Color'],b.inputs['Height']); l.new(b.outputs[0],bs.inputs['Normal'])\n    else:\n        # Concrete source is weathered: lighten it into a sealed residential slab.\n        mix=n.new('ShaderNodeMixRGB'); mix.blend_type='MIX'; mix.inputs[0].default_value=.50\n        mix.inputs[2].default_value=(.46,.43,.37,1)\n        l.new(diff.outputs['Color'],mix.inputs[1]); l.new(mix.outputs[0],bs.inputs['Base Color'])\n        rough=n.new('ShaderNodeTexImage'); rough.image=bpy.data.images.load(str(ASSETS/f'{stem}_rough_2k.jpg'),check_existing=True)\n        rough.image.colorspace_settings.name='Non-Color'\n        l.new(mapping.outputs[0],rough.inputs['Vector'])\n        remap=n.new('ShaderNodeMapRange'); remap.inputs['To Min'].default_value=.38; remap.inputs['To Max'].default_value=.65\n        l.new(rough.outputs['Color'],remap.inputs['Value']); l.new(remap.outputs[0],bs.inputs['Roughness'])\n        norm=n.new('ShaderNodeTexImage'); norm.image=bpy.data.images.load(str(ASSETS/f'{stem}_nor_gl_2k.jpg'),check_existing=True)\n        norm.image.colorspace_settings.name='Non-Color'; l.new(mapping.outputs[0],norm.inputs['Vector'])\n        normal=n.new('ShaderNodeNormalMap'); normal.inputs['Strength'].default_value=.18\n        l.new(norm.outputs['Color'],normal.inputs['Color']); l.new(normal.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef import_mesh(path,name):\n    \"\"\"Evaluate GLB hierarchy/skin and bake once before rescaling in world units.\"\"\"\n    before=set(bpy.data.objects); bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=set(bpy.data.objects)-before\n    bpy.context.view_layer.update(); deps=bpy.context.evaluated_depsgraph_get(); result=[]\n    for o in imported:\n        if o.type!='MESH': continue\n        mesh=bpy.data.meshes.new_from_object(o.evaluated_get(deps),depsgraph=deps)\n        mesh.transform(o.matrix_world)\n        obj=bpy.data.objects.new(name,mesh); bpy.context.collection.objects.link(obj); result.append(obj)\n    for o in imported: bpy.data.objects.remove(o,do_unlink=True)\n    bpy.ops.object.select_all(action='DESELECT')\n    for o in result: o.select_set(True)\n    bpy.context.view_layer.objects.active=result[0]\n    if len(result)>1: bpy.ops.object.join()\n    return bpy.context.object\n\ndef make_ball(filename,key,radius):\n    o=import_mesh(MODELS/filename,key)\n    lo=Vector(tuple(min(v.co[i] for v in o.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in o.data.vertices) for i in range(3)))\n    c=(lo+hi)/2\n    outer=max((v.co-c).length for v in o.data.vertices)\n    for v in o.data.vertices: v.co=(v.co-c)*(radius/outer)\n    o.data.update(); o.name=key\n    for f in o.data.polygons: f.use_smooth=True\n    for m in o.data.materials:\n        if not m or not m.use_nodes: continue\n        for n in m.node_tree.nodes:\n            if n.type!='BSDF_PRINCIPLED': continue\n            for field,value in [('Metallic',0.),('Roughness',.57 if key=='soccer' else .72),('Emission Strength',0.)]:\n                for link in list(n.inputs[field].links): m.node_tree.links.remove(link)\n                n.inputs[field].default_value=value\n    # Fixed mesh-space orientation, independent of physical centre and quaternion.\n    o.data.transform(Matrix.Rotation(.36 if key=='soccer' else .55,4,'X') @ Matrix.Rotation(.38,4,'Z'))\n    return o\n\ndef build_room(s):\n    h=s['physics']['step_height']\n    plaster=material('Warm mineral plaster',(.62,.58,.49),.86,.0008)\n    cream=material('Ivory painted joinery',(.76,.74,.66),.44,.0002)\n    dark=material('Anodized bronze frames',(.065,.055,.042),.33)\n    oak=material('Oiled oak end grain',(.28,.15,.068),.50,.0007)\n    linen=material('Natural flax upholstery',(.50,.44,.34),.88,.0012)\n    concrete=scanned_surface('Sealed warm concrete','concrete_floor',.45)\n    wood=scanned_surface('Photographic worn oak floor','wood_floor_worn',.50,True)\n    for name,center,size in boxes(h):\n        if name=='back_wall': continue\n        cube(name,center,size,concrete if name=='floor' else wood if name=='platform' else plaster,\n             .0006 if name=='platform' else 0)\n    # Window opening in a continuous plaster wall; the actual daylight enters here.\n    y=ROOM_Y[1]+.1; xmin,xmax=ROOM_X; wl,wr=-1.75,.45; wb,wt=.82,2.72\n    for name,center,size in [\n        ('Back wall left',((xmin+wl)/2,y,1.6),(wl-xmin,.2,3.2)),\n        ('Back wall right',((wr+xmax)/2,y,1.6),(xmax-wr,.2,3.2)),\n        ('Under window',((wl+wr)/2,y,wb/2),(wr-wl,.2,wb)),\n        ('Above window',((wl+wr)/2,y,(wt+3.2)/2),(wr-wl,.2,3.2-wt))]: cube(name,center,size,plaster)\n    for x in (wl,wr,(wl+wr)/2): cube('Window vertical frame',(x,2.83,(wb+wt)/2),(.045,.08,wt-wb),dark,.002)\n    for z in (wb,wt,1.8): cube('Window horizontal frame',((wl+wr)/2,2.83,z),(wr-wl,.08,.042),dark,.002)\n    cube('Deep stone window sill',((wl+wr)/2,2.74,wb), (wr-wl+.1,.30,.05),cream,.006)\n    # Outdoor colour and a distant hedge give depth through the real opening.\n    sky=material('Overcast garden beyond window',(.62,.73,.80),1)\n    cube('Garden sky',(-.65,5.8,2.7),(6,.05,5.4),sky)\n    hedge=material('Soft garden green',(.12,.20,.075),.9,.02)\n    hn,hl=hedge.node_tree.nodes,hedge.node_tree.links\n    noise=hn.new('ShaderNodeTexNoise'); noise.inputs['Scale'].default_value=15\n    ramp=hn.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].color=(.025,.055,.012,1)\n    ramp.color_ramp.elements[1].color=(.19,.29,.085,1)\n    hl.new(noise.outputs['Fac'],ramp.inputs[0]); hl.new(ramp.outputs[0],hn.get('Principled BSDF').inputs['Base Color'])\n    rng=random.Random(92)\n    for i in range(17):\n        bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=rng.uniform(.3,.6),location=(-3+i*.3,5.2,rng.uniform(.25,.65)))\n        bpy.context.object.name='Distant garden foliage'; bpy.context.object.data.materials.append(hedge)\n        for f in bpy.context.object.data.polygons: f.use_smooth=True\n    glass=material('Lightly frosted privacy glazing',(.88,.94,.98),.25)\n    gn,gl=glass.node_tree.nodes,glass.node_tree.links\n    gbs=gn.get('Principled BSDF'); gbs.inputs['Transmission Weight'].default_value=1\n    gbs.inputs['IOR'].default_value=1.45\n    # Transmitted daylight is supplied by the exterior area light, without noisy caustics.\n    lightpath=gn.new('ShaderNodeLightPath'); transparent=gn.new('ShaderNodeBsdfTransparent')\n    mix=gn.new('ShaderNodeMixShader'); gl.new(lightpath.outputs['Is Shadow Ray'],mix.inputs[0])\n    gl.new(gbs.outputs[0],mix.inputs[1]); gl.new(transparent.outputs[0],mix.inputs[2])\n    gl.new(mix.outputs[0],gn.get('Material Output').inputs['Surface'])\n    cube('Privacy window glazing',((wl+wr)/2,2.88,(wb+wt)/2),(wr-wl,.008,wt-wb),glass)\n    # Low built-in bench stays well away from the ball lane (y=-0.18).\n    for x in (1.30,3.35): cube('Bench leg',(x,2.27,h+.19),(.075,.48,.38),oak,.009)\n    cube('Oak bench seat',(2.325,2.27,h+.395),(2.35,.64,.08),oak,.018)\n    cube('Flax seat cushion',(2.325,2.24,h+.47),(2.24,.57,.095),linen,.038)\n    # Wall artwork: physical frame, mat, paper and raised abstract pigment.\n    cube('Oak picture frame',(2.5,2.72,1.72),(.94,.05,1.08),oak,.006)\n    cube('Ivory print mount',(2.5,2.686,1.72),(.89,.012,1.03),cream)\n    paper=material('Textured cotton art paper',(.64,.57,.43),.94,.0005)\n    rust=material('Abstract clay pigment',(.35,.13,.065),.95)\n    cube('Artwork paper',(2.5,2.678,1.72),(.68,.006,.81),paper)\n    cube('Artwork pigment',(2.43,2.673,1.67),(.27,.002,.49),rust,.06)\n    cube('Artwork charcoal accent',(2.69,2.672,1.9),(.10,.002,.20),dark)\n    # Floor skirting follows both levels; the curb riser remains fully visible.\n    cube('Back skirting lower',(-1.9,2.785,.045),(3.8,.03,.09),cream,.002)\n    cube('Back skirting upper',(2.6,2.785,h+.045),(5.2,.03,.09),cream,.002)\n    cube('Right skirting',(5.185,-.5,h+.045),(.03,6.6,.09),cream,.002)\n    cube('Ceiling',(.7,-.5,3.26),(9.2,6.8,.12),cream)\n    # Keep the fig's original leaf/pot proportions with one uniform metre-scale factor.\n    plant=import_mesh(MODELS/PLANT_ASSET,'Fiddle Leaf Fig / supplied textured mesh')\n    lo=Vector(tuple(min(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    hi=Vector(tuple(max(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    native_height=hi.z-lo.z\n    if native_height<=0: raise ValueError('Fiddle Leaf Fig has zero height')\n    # Anchor the pot rather than the asymmetric canopy, and put its bottom on the slab.\n    base=[v.co for v in plant.data.vertices if v.co.z <= lo.z+native_height*.12]\n    center=Vector(((min(v.x for v in base)+max(v.x for v in base))/2,\n                   (min(v.y for v in base)+max(v.y for v in base))/2,lo.z))\n    scale=PLANT_HEIGHT_M/native_height\n    for v in plant.data.vertices: v.co=(v.co-center)*scale\n    plant.data.update()\n    plant.location=(*PLANT_POSITION_XY,h)\n    plant['source_asset']=str(MODELS/PLANT_ASSET)\n    plant['height_m']=PLANT_HEIGHT_M\n    plant['uniform_scale_from_source']=scale\n    plant.rotation_euler.z=math.radians(PLANT_ROTATION_DEG)\n    from .plant_styling import integrate_scan,ceramic_planter\n    integrate_scan(plant,PLANT_HEIGHT_M)\n    ceramic_planter(plant.location,material)\n    scene=bpy.context.scene\n    scene.world=bpy.data.worlds.new('Daylight interior world'); scene.world.use_nodes=True\n    bg=scene.world.node_tree.nodes.get('Background'); bg.inputs['Color'].default_value=(.65,.74,.84,1); bg.inputs['Strength'].default_value=.16\n    area('Large window soft daylight',(-.7,3.12,2.05),(.2,-.6,.1),360,1.9,(.84,.91,1.))\n    area('Warm interior bounce',(-2.8,-2.0,2.5),(.5,.3,.2),100,3.0,(1.,.86,.69))\n    area('Ceiling reflected light',(2.2,.2,3.05),(.5,-.3,0),80,2.5,(1.,.94,.83))\n    area('Soft reflected daylight near bench',(2.9,-.2,2.2),(3.92,1.82,.95),35,1.3,(1.,.96,.85))\n    # Grazing afternoon light casts the mullion shadows onto the lower floor.\n    bpy.ops.object.light_add(type='SUN',location=(-2,4,5))\n    sun=bpy.context.object; sun.name='Afternoon sun through rear window'; sun.data.energy=1.6\n    sun.data.angle=math.radians(7); sun.data.color=(1.,.89,.72); aim(sun,(.8,-1.4,0))\n", "scene_geometry": "\"\"\"One source of truth for visible surfaces and Bullet collision geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS = ('soccer','basketball')\nRADII = (.11,.12)\nSTART_X = (-1.55,.82)\nLANE_Y = -.18\nSIM_HZ = 1440\nROOM_X = (-3.8,5.2)\nROOM_Y = (-3.8,2.8)\nSTEP_X = 0.\nFLOOR_THICKNESS = .16\n\ndef boxes(height):\n    \"\"\"(name, centre, full size). Top surfaces are exactly z=0 and z=height.\"\"\"\n    x0,x1=ROOM_X; y0,y1=ROOM_Y\n    return [\n        ('floor',((x0+x1)/2,(y0+y1)/2,-FLOOR_THICKNESS/2),\n            (x1-x0,y1-y0,FLOOR_THICKNESS)),\n        ('platform',((STEP_X+x1)/2,(y0+y1)/2,height/2),\n            (x1-STEP_X,y1-y0,height)),\n        ('back_wall',((x0+x1)/2,y1+.10,1.6),(x1-x0,.20,3.2)),\n        ('right_wall',(x1+.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2)),\n        ('left_wall',(x0-.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2))]\n\ndef constants():\n    return dict(radii_m=RADII,start_x_m=START_X,lane_y_m=LANE_Y,\n                step_x_m=STEP_X,room_x_m=ROOM_X,room_y_m=ROOM_Y,simulation_hz=SIM_HZ,\n                floor_friction=.65,platform_friction=.65,surface_restitution=.22,\n                floor_rolling_friction=.0015,ball_lateral_friction=.8)\n", "soccer_step_collision.cache_contract": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nfrom .scene_geometry import KEYS, constants\nfrom .scene_config import validate, SCENE_NAME\n\nfrom .runtime_support import HERE, ROOT\ndef signature(s):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=s)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(d):\n    s=d['scenario']; validate(s)\n    if d['scene'] != SCENE_NAME or d.get('simulation_signature') != signature(s):\n        raise ValueError('Stale or foreign physics cache; resimulate')\n    count=round(s['render']['fps']*s['render']['duration_sec'])\n    if len(d['frames']) != count or d['frame_end'] != count: raise ValueError('Incomplete trajectory')\n    if not d['quality']['valid']: raise ValueError('Physics trace failed validation')\n    for i,row in enumerate(d['frames']):\n        if row['frame_index'] != i+1 or abs(row['time_sec']-i/d['fps'])>1e-9:\n            raise ValueError('Invalid frame clock')\n        for k in KEYS:\n            if not all(math.isfinite(v) for field in ('location','quaternion_xyzw','linear_velocity','angular_velocity') for v in row[k][field]):\n                raise ValueError('Nonfinite rigid-body state')\n", "soccer_step_collision.plant_styling": "\"\"\"Integrate the supplied fig scan with neutral ceramics and room lighting.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nimport bpy\n\ndef ceramic_planter(base,material_factory):\n    clay=material_factory('Warm greige matte stoneware',(.30,.27,.22),.76,.0007)\n    # A hollow tapered sleeve surrounds the original small scanned pot.\n    profile=[(.126,0),(.131,.009),(.176,.260),(.180,.270),(.180,.280),\n             (.176,.285),(.169,.283),(.165,.271),(.122,.028)]\n    n=80; vertices=[]; faces=[]\n    for radius,z in profile:\n        vertices.extend([(radius*math.cos(i*math.tau/n),radius*math.sin(i*math.tau/n),z) for i in range(n)])\n    for j in range(len(profile)-1):\n        for i in range(n):\n            a=j*n+i; b=j*n+(i+1)%n; c=(j+1)*n+(i+1)%n; d=(j+1)*n+i\n            faces.append((a,b,c,d))\n    faces.append(tuple(reversed(range(n))))\n    faces.append(tuple((len(profile)-1)*n+i for i in range(n)))\n    mesh=bpy.data.meshes.new('Closed hollow stoneware profile'); mesh.from_pydata(vertices,[],faces); mesh.update()\n    obj=bpy.data.objects.new('Matte ceramic outer planter',mesh); bpy.context.collection.objects.link(obj)\n    obj.location=base; mesh.materials.append(clay)\n    for f in mesh.polygons: f.use_smooth=len(f.vertices)==4\n    soil=material_factory('Dark potting soil',(.025,.018,.009),.97,.003)\n    bpy.ops.mesh.primitive_cylinder_add(vertices=80,radius=.164,depth=.016,location=(base.x,base.y,base.z+.252))\n    bpy.context.object.name='Recessed potting soil'; bpy.context.object.data.materials.append(soil)\n    return obj\n\ndef integrate_scan(plant,height):\n    \"\"\"Remove the scan's cyan cast while retaining its original UV and leaf detail.\"\"\"\n    for mat in plant.data.materials:\n        if not mat or not mat.use_nodes: continue\n        images=[node.image for node in mat.node_tree.nodes if node.type=='TEX_IMAGE' and node.image]\n        if not images: raise ValueError('Fiddle Leaf Fig material has no albedo texture')\n        albedo=images[0]; nodes,links=mat.node_tree.nodes,mat.node_tree.links\n        nodes.clear()\n        tex=nodes.new('ShaderNodeTexImage'); tex.image=albedo\n        luminance=nodes.new('ShaderNodeRGBToBW'); links.new(tex.outputs['Color'],luminance.inputs[0])\n        tonal=nodes.new('ShaderNodeMapRange'); tonal.inputs['From Min'].default_value=.025\n        tonal.inputs['From Max'].default_value=.60\n        links.new(luminance.outputs[0],tonal.inputs['Value'])\n        green=nodes.new('ShaderNodeValToRGB')\n        green.color_ramp.elements[0].color=(.025,.065,.012,1)\n        green.color_ramp.elements[1].color=(.24,.36,.065,1)\n        green.color_ramp.elements.new(.45).color=(.075,.155,.024,1)\n        links.new(tonal.outputs[0],green.inputs[0])\n        blend=nodes.new('ShaderNodeMixRGB'); blend.inputs[0].default_value=.68\n        links.new(tex.outputs['Color'],blend.inputs[1]); links.new(green.outputs[0],blend.inputs[2])\n        leaf=nodes.new('ShaderNodeBsdfPrincipled')\n        leaf.inputs['Roughness'].default_value=.64\n        leaf.inputs['Specular IOR Level'].default_value=.25\n        leaf.inputs['Subsurface Weight'].default_value=.025\n        links.new(blend.outputs[0],leaf.inputs['Base Color'])\n        brown=nodes.new('ShaderNodeValToRGB')\n        brown.color_ramp.elements[0].color=(.018,.010,.005,1)\n        brown.color_ramp.elements[1].color=(.18,.10,.035,1)\n        links.new(tonal.outputs[0],brown.inputs[0])\n        stem=nodes.new('ShaderNodeBsdfPrincipled'); stem.inputs['Roughness'].default_value=.85\n        links.new(brown.outputs[0],stem.inputs['Base Color'])\n        coord=nodes.new('ShaderNodeTexCoord'); xyz=nodes.new('ShaderNodeSeparateXYZ')\n        links.new(coord.outputs['Object'],xyz.inputs[0])\n        mask=nodes.new('ShaderNodeMapRange'); mask.inputs['From Min'].default_value=height*.43\n        mask.inputs['From Max'].default_value=height*.55\n        links.new(xyz.outputs['Z'],mask.inputs['Value'])\n        mix=nodes.new('ShaderNodeMixShader'); links.new(mask.outputs[0],mix.inputs[0])\n        links.new(stem.outputs[0],mix.inputs[1]); links.new(leaf.outputs[0],mix.inputs[2])\n        out=nodes.new('ShaderNodeOutputMaterial'); links.new(mix.outputs[0],out.inputs['Surface'])\n", "soccer_step_collision.runtime_support": "from pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\nHERE = _PCVE_SCENE_ROOT\nMODELS = ROOT / 'assets' / 'models'\nASSETS = ROOT / 'assets' / 'polyhaven' / 'soccer_step_collision'\n\nfrom pcve_scene_runtime import python_for, render_prefix\n", "soccer_step_collision.scene_config": "\"\"\"Strict metre/kilogram/second scenario contract, shared by simulation and render.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json\nimport math\nfrom pathlib import Path\n\nSCENE_NAME = 'soccer_step_collision'\nBASELINE_PHYSICS = dict(soccer_mass=.43, basketball_mass=.62, launch_speed=1.95,\n    step_height=.045, surface_rolling_friction=.0015,\n    soccer_restitution=.72, basketball_restitution=.78)\nLIMITS = dict(soccer_mass=(.05,5), basketball_mass=(.05,5), launch_speed=(.1,3),\n    step_height=(.005,.20), surface_rolling_friction=(0,.1),\n    soccer_restitution=(0,1), basketball_restitution=(0,1))\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME, seed=0,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=4., resolution=[960,540], samples=40),\n        camera=dict(location=[-2.6,-5.5,2.15], target=[.55,.1,.35], lens_mm=48))\n\ndef merge(base, override):\n    result = deepcopy(base)\n    if not isinstance(override, dict): raise ValueError('Override must be an object')\n    for k,v in override.items():\n        if k not in base: raise ValueError(f'Unknown scenario field: {k}')\n        result[k] = merge(base[k],v) if isinstance(base[k],dict) else deepcopy(v)\n    return result\n\ndef finite(x):\n    return type(x) in (int,float) and math.isfinite(x)\n\ndef validate(s):\n    if set(s) != set(defaults()) or s['scene'] != SCENE_NAME or s['schema_version'] != 1:\n        raise ValueError('Wrong scenario schema')\n    if set(s['physics']) != set(BASELINE_PHYSICS): raise ValueError('Unknown physics field')\n    for k,(lo,hi) in LIMITS.items():\n        if not finite(s['physics'][k]) or not lo <= s['physics'][k] <= hi:\n            raise ValueError(f'{k} must be within {lo}..{hi}')\n    r=s['render']\n    if set(r) != set(defaults()['render']): raise ValueError('Unknown render field')\n    if type(r['fps']) is not int or r['fps'] <= 0 or 1440 % r['fps']:\n        raise ValueError('fps must divide the 1440 Hz simulation clock')\n    if not finite(r['duration_sec']) or not .1 <= r['duration_sec'] <= 30:\n        raise ValueError('Invalid duration')\n    if len(r['resolution']) != 2 or any(type(v) is not int or v<16 for v in r['resolution']):\n        raise ValueError('Invalid resolution')\n    if type(r['samples']) is not int or r['samples']<1: raise ValueError('Invalid samples')\n    c=s['camera']\n    if set(c) != set(defaults()['camera']): raise ValueError('Unknown camera field')\n    for k in ('location','target'):\n        if len(c[k]) != 3 or not all(finite(v) for v in c[k]): raise ValueError('Invalid camera vector')\n    if not finite(c['lens_mm']) or c['lens_mm']<=0: raise ValueError('Invalid lens')\n\ndef load_scenario(path=None, override=None):\n    s=defaults()\n    for p in (path,override):\n        if p: s=merge(s,json.loads(Path(p).read_text(encoding='utf-8')))\n    validate(s)\n    return s\n\ndef write_json(path, data):\n    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)\n    path.write_text(json.dumps(data,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')\n", "soccer_step_collision.scene_environment": "\"\"\"A daylight split-level sitting room; all geometry is authored at metre scale.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport math\nfrom pathlib import Path\nimport random\nimport bpy\nfrom mathutils import Vector, Matrix\nfrom .runtime_support import MODELS, ASSETS\nfrom .scene_geometry import boxes, ROOM_X, ROOM_Y\n\nPLANT_ASSET = 'fiddle_leaf_fig.glb'\nPLANT_HEIGHT_M = 1.24\nPLANT_POSITION_XY = (3.92, 1.82)\nPLANT_ROTATION_DEG = 135.\n\ndef material(name,color,roughness=.6,bump=0):\n    m=bpy.data.materials.new(name); m.use_nodes=True\n    bs=m.node_tree.nodes.get('Principled BSDF')\n    bs.inputs['Base Color'].default_value=(*color,1)\n    bs.inputs['Roughness'].default_value=roughness\n    if bump:\n        n=m.node_tree.nodes.new('ShaderNodeTexNoise'); n.inputs['Scale'].default_value=180\n        t=m.node_tree.nodes.new('ShaderNodeTexCoord')\n        m.node_tree.links.new(t.outputs['Object'],n.inputs['Vector'])\n        b=m.node_tree.nodes.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.22\n        b.inputs['Distance'].default_value=bump\n        m.node_tree.links.new(n.outputs['Fac'],b.inputs['Height'])\n        m.node_tree.links.new(b.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef cube(name,center,size,mat,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=center)\n    o=bpy.context.object; o.name=name; o.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)\n    o.data.materials.append(mat)\n    if bevel:\n        mod=o.modifiers.new('Small real edge radius','BEVEL'); mod.width=bevel; mod.segments=3\n        o.modifiers.new('Weighted corner normals','WEIGHTED_NORMAL')\n    return o\n\ndef aim(obj,point):\n    obj.rotation_euler=(Vector(point)-obj.location).to_track_quat('-Z','Y').to_euler()\n\ndef area(name,pos,target,power,size,color):\n    d=bpy.data.lights.new(name,'AREA'); d.energy=power; d.shape='DISK'; d.size=size; d.color=color\n    o=bpy.data.objects.new(name,d); bpy.context.collection.objects.link(o); o.location=pos; aim(o,target)\n\ndef scanned_surface(name,stem,scale,wood=False):\n    m=material(name,(.4,.35,.27),.48)\n    n,l=m.node_tree.nodes,m.node_tree.links; bs=n.get('Principled BSDF')\n    uv=n.new('ShaderNodeTexCoord'); mapping=n.new('ShaderNodeVectorMath'); mapping.operation='SCALE'\n    mapping.inputs['Scale'].default_value=scale\n    l.new(uv.outputs['Object'],mapping.inputs[0])\n    diff=n.new('ShaderNodeTexImage'); diff.image=bpy.data.images.load(str(ASSETS/f'{stem}_diff_2k.jpg'),check_existing=True)\n    l.new(mapping.outputs['Vector'],diff.inputs['Vector']); l.new(diff.outputs['Color'],bs.inputs['Base Color'])\n    if wood:\n        b=n.new('ShaderNodeBump'); b.inputs['Strength'].default_value=.15; b.inputs['Distance'].default_value=.0015\n        l.new(diff.outputs['Color'],b.inputs['Height']); l.new(b.outputs[0],bs.inputs['Normal'])\n    else:\n        # Concrete source is weathered: lighten it into a sealed residential slab.\n        mix=n.new('ShaderNodeMixRGB'); mix.blend_type='MIX'; mix.inputs[0].default_value=.50\n        mix.inputs[2].default_value=(.46,.43,.37,1)\n        l.new(diff.outputs['Color'],mix.inputs[1]); l.new(mix.outputs[0],bs.inputs['Base Color'])\n        rough=n.new('ShaderNodeTexImage'); rough.image=bpy.data.images.load(str(ASSETS/f'{stem}_rough_2k.jpg'),check_existing=True)\n        rough.image.colorspace_settings.name='Non-Color'\n        l.new(mapping.outputs[0],rough.inputs['Vector'])\n        remap=n.new('ShaderNodeMapRange'); remap.inputs['To Min'].default_value=.38; remap.inputs['To Max'].default_value=.65\n        l.new(rough.outputs['Color'],remap.inputs['Value']); l.new(remap.outputs[0],bs.inputs['Roughness'])\n        norm=n.new('ShaderNodeTexImage'); norm.image=bpy.data.images.load(str(ASSETS/f'{stem}_nor_gl_2k.jpg'),check_existing=True)\n        norm.image.colorspace_settings.name='Non-Color'; l.new(mapping.outputs[0],norm.inputs['Vector'])\n        normal=n.new('ShaderNodeNormalMap'); normal.inputs['Strength'].default_value=.18\n        l.new(norm.outputs['Color'],normal.inputs['Color']); l.new(normal.outputs[0],bs.inputs['Normal'])\n    return m\n\ndef import_mesh(path,name):\n    \"\"\"Evaluate GLB hierarchy/skin and bake once before rescaling in world units.\"\"\"\n    before=set(bpy.data.objects); bpy.ops.import_scene.gltf(filepath=str(path))\n    imported=set(bpy.data.objects)-before\n    bpy.context.view_layer.update(); deps=bpy.context.evaluated_depsgraph_get(); result=[]\n    for o in imported:\n        if o.type!='MESH': continue\n        mesh=bpy.data.meshes.new_from_object(o.evaluated_get(deps),depsgraph=deps)\n        mesh.transform(o.matrix_world)\n        obj=bpy.data.objects.new(name,mesh); bpy.context.collection.objects.link(obj); result.append(obj)\n    for o in imported: bpy.data.objects.remove(o,do_unlink=True)\n    bpy.ops.object.select_all(action='DESELECT')\n    for o in result: o.select_set(True)\n    bpy.context.view_layer.objects.active=result[0]\n    if len(result)>1: bpy.ops.object.join()\n    return bpy.context.object\n\ndef make_ball(filename,key,radius):\n    o=import_mesh(MODELS/filename,key)\n    lo=Vector(tuple(min(v.co[i] for v in o.data.vertices) for i in range(3)))\n    hi=Vector(tuple(max(v.co[i] for v in o.data.vertices) for i in range(3)))\n    c=(lo+hi)/2\n    outer=max((v.co-c).length for v in o.data.vertices)\n    for v in o.data.vertices: v.co=(v.co-c)*(radius/outer)\n    o.data.update(); o.name=key\n    for f in o.data.polygons: f.use_smooth=True\n    for m in o.data.materials:\n        if not m or not m.use_nodes: continue\n        for n in m.node_tree.nodes:\n            if n.type!='BSDF_PRINCIPLED': continue\n            for field,value in [('Metallic',0.),('Roughness',.57 if key=='soccer' else .72),('Emission Strength',0.)]:\n                for link in list(n.inputs[field].links): m.node_tree.links.remove(link)\n                n.inputs[field].default_value=value\n    # Fixed mesh-space orientation, independent of physical centre and quaternion.\n    o.data.transform(Matrix.Rotation(.36 if key=='soccer' else .55,4,'X') @ Matrix.Rotation(.38,4,'Z'))\n    return o\n\ndef build_room(s):\n    h=s['physics']['step_height']\n    plaster=material('Warm mineral plaster',(.62,.58,.49),.86,.0008)\n    cream=material('Ivory painted joinery',(.76,.74,.66),.44,.0002)\n    dark=material('Anodized bronze frames',(.065,.055,.042),.33)\n    oak=material('Oiled oak end grain',(.28,.15,.068),.50,.0007)\n    linen=material('Natural flax upholstery',(.50,.44,.34),.88,.0012)\n    concrete=scanned_surface('Sealed warm concrete','concrete_floor',.45)\n    wood=scanned_surface('Photographic worn oak floor','wood_floor_worn',.50,True)\n    for name,center,size in boxes(h):\n        if name=='back_wall': continue\n        cube(name,center,size,concrete if name=='floor' else wood if name=='platform' else plaster,\n             .0006 if name=='platform' else 0)\n    # Window opening in a continuous plaster wall; the actual daylight enters here.\n    y=ROOM_Y[1]+.1; xmin,xmax=ROOM_X; wl,wr=-1.75,.45; wb,wt=.82,2.72\n    for name,center,size in [\n        ('Back wall left',((xmin+wl)/2,y,1.6),(wl-xmin,.2,3.2)),\n        ('Back wall right',((wr+xmax)/2,y,1.6),(xmax-wr,.2,3.2)),\n        ('Under window',((wl+wr)/2,y,wb/2),(wr-wl,.2,wb)),\n        ('Above window',((wl+wr)/2,y,(wt+3.2)/2),(wr-wl,.2,3.2-wt))]: cube(name,center,size,plaster)\n    for x in (wl,wr,(wl+wr)/2): cube('Window vertical frame',(x,2.83,(wb+wt)/2),(.045,.08,wt-wb),dark,.002)\n    for z in (wb,wt,1.8): cube('Window horizontal frame',((wl+wr)/2,2.83,z),(wr-wl,.08,.042),dark,.002)\n    cube('Deep stone window sill',((wl+wr)/2,2.74,wb), (wr-wl+.1,.30,.05),cream,.006)\n    # Outdoor colour and a distant hedge give depth through the real opening.\n    sky=material('Overcast garden beyond window',(.62,.73,.80),1)\n    cube('Garden sky',(-.65,5.8,2.7),(6,.05,5.4),sky)\n    hedge=material('Soft garden green',(.12,.20,.075),.9,.02)\n    hn,hl=hedge.node_tree.nodes,hedge.node_tree.links\n    noise=hn.new('ShaderNodeTexNoise'); noise.inputs['Scale'].default_value=15\n    ramp=hn.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].color=(.025,.055,.012,1)\n    ramp.color_ramp.elements[1].color=(.19,.29,.085,1)\n    hl.new(noise.outputs['Fac'],ramp.inputs[0]); hl.new(ramp.outputs[0],hn.get('Principled BSDF').inputs['Base Color'])\n    rng=random.Random(92)\n    for i in range(17):\n        bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=rng.uniform(.3,.6),location=(-3+i*.3,5.2,rng.uniform(.25,.65)))\n        bpy.context.object.name='Distant garden foliage'; bpy.context.object.data.materials.append(hedge)\n        for f in bpy.context.object.data.polygons: f.use_smooth=True\n    glass=material('Lightly frosted privacy glazing',(.88,.94,.98),.25)\n    gn,gl=glass.node_tree.nodes,glass.node_tree.links\n    gbs=gn.get('Principled BSDF'); gbs.inputs['Transmission Weight'].default_value=1\n    gbs.inputs['IOR'].default_value=1.45\n    # Transmitted daylight is supplied by the exterior area light, without noisy caustics.\n    lightpath=gn.new('ShaderNodeLightPath'); transparent=gn.new('ShaderNodeBsdfTransparent')\n    mix=gn.new('ShaderNodeMixShader'); gl.new(lightpath.outputs['Is Shadow Ray'],mix.inputs[0])\n    gl.new(gbs.outputs[0],mix.inputs[1]); gl.new(transparent.outputs[0],mix.inputs[2])\n    gl.new(mix.outputs[0],gn.get('Material Output').inputs['Surface'])\n    cube('Privacy window glazing',((wl+wr)/2,2.88,(wb+wt)/2),(wr-wl,.008,wt-wb),glass)\n    # Low built-in bench stays well away from the ball lane (y=-0.18).\n    for x in (1.30,3.35): cube('Bench leg',(x,2.27,h+.19),(.075,.48,.38),oak,.009)\n    cube('Oak bench seat',(2.325,2.27,h+.395),(2.35,.64,.08),oak,.018)\n    cube('Flax seat cushion',(2.325,2.24,h+.47),(2.24,.57,.095),linen,.038)\n    # Wall artwork: physical frame, mat, paper and raised abstract pigment.\n    cube('Oak picture frame',(2.5,2.72,1.72),(.94,.05,1.08),oak,.006)\n    cube('Ivory print mount',(2.5,2.686,1.72),(.89,.012,1.03),cream)\n    paper=material('Textured cotton art paper',(.64,.57,.43),.94,.0005)\n    rust=material('Abstract clay pigment',(.35,.13,.065),.95)\n    cube('Artwork paper',(2.5,2.678,1.72),(.68,.006,.81),paper)\n    cube('Artwork pigment',(2.43,2.673,1.67),(.27,.002,.49),rust,.06)\n    cube('Artwork charcoal accent',(2.69,2.672,1.9),(.10,.002,.20),dark)\n    # Floor skirting follows both levels; the curb riser remains fully visible.\n    cube('Back skirting lower',(-1.9,2.785,.045),(3.8,.03,.09),cream,.002)\n    cube('Back skirting upper',(2.6,2.785,h+.045),(5.2,.03,.09),cream,.002)\n    cube('Right skirting',(5.185,-.5,h+.045),(.03,6.6,.09),cream,.002)\n    cube('Ceiling',(.7,-.5,3.26),(9.2,6.8,.12),cream)\n    # Keep the fig's original leaf/pot proportions with one uniform metre-scale factor.\n    plant=import_mesh(MODELS/PLANT_ASSET,'Fiddle Leaf Fig / supplied textured mesh')\n    lo=Vector(tuple(min(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    hi=Vector(tuple(max(v.co[j] for v in plant.data.vertices) for j in range(3)))\n    native_height=hi.z-lo.z\n    if native_height<=0: raise ValueError('Fiddle Leaf Fig has zero height')\n    # Anchor the pot rather than the asymmetric canopy, and put its bottom on the slab.\n    base=[v.co for v in plant.data.vertices if v.co.z <= lo.z+native_height*.12]\n    center=Vector(((min(v.x for v in base)+max(v.x for v in base))/2,\n                   (min(v.y for v in base)+max(v.y for v in base))/2,lo.z))\n    scale=PLANT_HEIGHT_M/native_height\n    for v in plant.data.vertices: v.co=(v.co-center)*scale\n    plant.data.update()\n    plant.location=(*PLANT_POSITION_XY,h)\n    plant['source_asset']=str(MODELS/PLANT_ASSET)\n    plant['height_m']=PLANT_HEIGHT_M\n    plant['uniform_scale_from_source']=scale\n    plant.rotation_euler.z=math.radians(PLANT_ROTATION_DEG)\n    from .plant_styling import integrate_scan,ceramic_planter\n    integrate_scan(plant,PLANT_HEIGHT_M)\n    ceramic_planter(plant.location,material)\n    scene=bpy.context.scene\n    scene.world=bpy.data.worlds.new('Daylight interior world'); scene.world.use_nodes=True\n    bg=scene.world.node_tree.nodes.get('Background'); bg.inputs['Color'].default_value=(.65,.74,.84,1); bg.inputs['Strength'].default_value=.16\n    area('Large window soft daylight',(-.7,3.12,2.05),(.2,-.6,.1),360,1.9,(.84,.91,1.))\n    area('Warm interior bounce',(-2.8,-2.0,2.5),(.5,.3,.2),100,3.0,(1.,.86,.69))\n    area('Ceiling reflected light',(2.2,.2,3.05),(.5,-.3,0),80,2.5,(1.,.94,.83))\n    area('Soft reflected daylight near bench',(2.9,-.2,2.2),(3.92,1.82,.95),35,1.3,(1.,.96,.85))\n    # Grazing afternoon light casts the mullion shadows onto the lower floor.\n    bpy.ops.object.light_add(type='SUN',location=(-2,4,5))\n    sun=bpy.context.object; sun.name='Afternoon sun through rear window'; sun.data.energy=1.6\n    sun.data.angle=math.radians(7); sun.data.color=(1.,.89,.72); aim(sun,(.8,-1.4,0))\n", "soccer_step_collision.scene_geometry": "\"\"\"One source of truth for visible surfaces and Bullet collision geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nKEYS = ('soccer','basketball')\nRADII = (.11,.12)\nSTART_X = (-1.55,.82)\nLANE_Y = -.18\nSIM_HZ = 1440\nROOM_X = (-3.8,5.2)\nROOM_Y = (-3.8,2.8)\nSTEP_X = 0.\nFLOOR_THICKNESS = .16\n\ndef boxes(height):\n    \"\"\"(name, centre, full size). Top surfaces are exactly z=0 and z=height.\"\"\"\n    x0,x1=ROOM_X; y0,y1=ROOM_Y\n    return [\n        ('floor',((x0+x1)/2,(y0+y1)/2,-FLOOR_THICKNESS/2),\n            (x1-x0,y1-y0,FLOOR_THICKNESS)),\n        ('platform',((STEP_X+x1)/2,(y0+y1)/2,height/2),\n            (x1-STEP_X,y1-y0,height)),\n        ('back_wall',((x0+x1)/2,y1+.10,1.6),(x1-x0,.20,3.2)),\n        ('right_wall',(x1+.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2)),\n        ('left_wall',(x0-.1,(y0+y1)/2,1.6),(.20,y1-y0,3.2))]\n\ndef constants():\n    return dict(radii_m=RADII,start_x_m=START_X,lane_y_m=LANE_Y,\n                step_x_m=STEP_X,room_x_m=ROOM_X,room_y_m=ROOM_Y,simulation_hz=SIM_HZ,\n                floor_friction=.65,platform_friction=.65,surface_restitution=.22,\n                floor_rolling_friction=.0015,ball_lateral_friction=.8)\n", "soccer_step_collision": "\"\"\"Soccer ball climbs a real curb and collides with a resting basketball.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'soccer_step_collision'
_BUNDLE_ALIASES = ['cache_contract', 'plant_styling', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry', 'soccer_step_collision', 'soccer_step_collision.cache_contract', 'soccer_step_collision.plant_styling', 'soccer_step_collision.runtime_support', 'soccer_step_collision.scene_config', 'soccer_step_collision.scene_environment', 'soccer_step_collision.scene_geometry']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['cache_contract', 'plant_styling', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()



